function hmadb_source_names(array $e, ?array $obs=null): array {
    $src=$e['source']??($e['prior_evidence']['source']??[]); if(!is_array($src))$src=[];
    return array_values(array_unique(array_filter([(string)($src['name']??''),(string)($src['lName']??''),(string)($obs['hotel_name']??'')],static fn($v)=>trim($v)!=='')));
}
function hmadb_source_places(array $e, ?array $obs=null): array {
    $src=$e['source']??($e['prior_evidence']['source']??[]);if(!is_array($src))$src=[];$geo=$e['geography']??($e['prior_evidence']['geography']??[]);if(!is_array($geo))$geo=[];
    return array_values(array_unique(array_filter([(string)($src['town']??''),(string)($geo['town']??''),(string)($geo['parent']??''),(string)($obs['region_name']??'')],static fn($v)=>trim($v)!=='')));
}
